class CodeGenome:
    """Genetic representation of code"""
    
    def __init__(self, code: str):
        self.code = code
        self.genes = self._extract_genes(code)
        self.fitness = 0.0
        
    def _extract_genes(self, code: str) -> List[str]:
        """Extract genetic components from code"""
        try:
            tree = ast.parse(code)
            genes = []
            
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    genes.append(ast.unparse(node))
                elif isinstance(node, ast.ClassDef):
                    genes.append(ast.unparse(node))
            
            return genes
        except:
            return [code]  # Fallback to whole code as one gene
    
    def mutate(self, mutation_rate: float = 0.1) -> 'CodeGenome':
        """Mutate the code genome"""
        if random.random() < mutation_rate:
            # Simple mutation: modify a random gene
            if self.genes:
                mutated_genes = self.genes.copy()
                idx = random.randint(0, len(mutated_genes) - 1)
                
                # Add a comment as mutation (safe modification)
                mutated_genes[idx] = f"# Mutated at {datetime.now()}\n{mutated_genes[idx]}"
                
                mutated = CodeGenome("\n".join(mutated_genes))
                return mutated
        
        return self
    
    def crossover(self, other: 'CodeGenome') -> 'CodeGenome':
        """Crossover with another genome"""
        if not self.genes or not other.genes:
            return self
        
        # Simple crossover: mix genes
        crossover_point = random.randint(0, min(len(self.genes), len(other.genes)))
        
        new_genes = self.genes[:crossover_point] + other.genes[crossover_point:]
        offspring = CodeGenome("\n".join(new_genes))
        
        return offspring

class EvolutionEngine:
    """Engine for code evolution"""
    
    def __init__(self):
        self.generation = 0
        self.population: List[CodeGenome] = []
        self.best_genome: Optional[CodeGenome] = None
        self.mutation_rate = 0.1
        self.evolution_history: List[Dict[str, Any]] = []
        
    async def evolve_function(self, 
                             func: Callable,
                             generations: int = 10) -> Callable:
        """Evolve a function through genetic programming"""
        # Get source code
        source = inspect.getsource(func)
        
        # Create initial population
        self.population = [CodeGenome(source) for _ in range(10)]
        
        for gen in range(generations):
            self.generation = gen
            
            # Evaluate fitness
            await self._evaluate_population()
            
            # Selection
            survivors = self._select_fittest()
            
            # Reproduction
            offspring = self._reproduce(survivors)
            
            # Mutation
            self.population = [genome.mutate(self.mutation_rate) 
                              for genome in offspring]
            
            # Track best
            self.best_genome = max(self.population, key=lambda g: g.fitness)
            
            self.evolution_history.append({
                'generation': gen,
                'best_fitness': self.best_genome.fitness,
                'population_size': len(self.population)
            })
        
        # Return evolved function
        return self._compile_genome(self.best_genome)
    
    async def _evaluate_population(self):
        """Evaluate fitness of population"""
        for genome in self.population:
            # Simplified fitness: prefer shorter code
            genome.fitness = 1.0 / (len(genome.code) + 1)
            
            # Bonus for having multiple functions
            genome.fitness += len(genome.genes) * 0.1
    
    def _select_fittest(self) -> List[CodeGenome]:
        """Select fittest genomes"""
        # Sort by fitness
        sorted_pop = sorted(self.population, key=lambda g: g.fitness, reverse=True)
        
        # Keep top 50%
        return sorted_pop[:len(sorted_pop) // 2]
    
    def _reproduce(self, parents: List[CodeGenome]) -> List[CodeGenome]:
        """Create offspring from parents"""
        offspring = parents.copy()
        
        # Crossover to fill population
        while len(offspring) < 10:
            parent1 = random.choice(parents)
            parent2 = random.choice(parents)
            
            child = parent1.crossover(parent2)
            offspring.append(child)
        
        return offspring
    
    def _compile_genome(self, genome: CodeGenome) -> Callable:
        """Compile genome back to callable function"""
        try:
            # Create namespace for execution
            namespace = {}
            
            # Execute the code
            exec(genome.code, namespace)
            
            # Find and return first function
            for name, obj in namespace.items():
                if callable(obj) and not name.startswith('_'):
                    return obj
            
            # Fallback: return a dummy function
            return lambda *args, **kwargs: None
        except Exception as e:
            logger.error(f"Failed to compile genome: {e}")
            return lambda *args, **kwargs: None

class SelfModifyingMethod:
    """A method that can modify itself"""
    
    def __init__(self, initial_implementation: Callable):
        self.current_implementation = initial_implementation
        self.evolution_engine = EvolutionEngine()
        self.execution_count = 0
        self.performance_history: List[float] = []
        
    async def __call__(self, *args, **kwargs):
        """Execute and potentially evolve"""
        start_time = time.time()
        
        # Execute current implementation
        result = await self.current_implementation(*args, **kwargs) \
                 if asyncio.iscoroutinefunction(self.current_implementation) \
                 else self.current_implementation(*args, **kwargs)
        
        # Track performance
        execution_time = time.time() - start_time
        self.performance_history.append(execution_time)
        self.execution_count += 1
        
        # Evolve every 10 executions
        if self.execution_count % 10 == 0:
            await self._consider_evolution()
        
        return result
    
    async def _consider_evolution(self):
        """Consider evolving the implementation"""
        if len(self.performance_history) < 2:
            return
        
        # Check if performance is degrading
        recent_avg = sum(self.performance_history[-5:]) / 5
        overall_avg = sum(self.performance_history) / len(self.performance_history)
        
        if recent_avg > overall_avg * 1.1:  # 10% degradation
            logger.info("Performance degradation detected. Evolving...")
            
            # Evolve the implementation
            evolved = await self.evolution_engine.evolve_function(
                self.current_implementation,
                generations=5
            )
            
            if evolved:
                self.current_implementation = evolved
                logger.info("Evolution complete. New implementation deployed.")

