    async def configure_alerts(self, 
                             alert_config: Dict[str, Any]
                             ) -> Dict[str, Any]:
        """
        Unified alerting configuration for all monitoring types
        
        Args:
            alert_config: Alert configuration with thresholds and handlers
            
        Returns:
            Alert configuration results
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }
            
        try:
            default_thresholds = {
                'cpu_usage': 80,
                'memory_usage': 85,
                'error_rate': 5,
                'response_time': 2000,
                'dom_changes': 100,
                'console_errors': 10
            }
            
            # Merge with user config
            thresholds = {**default_thresholds, **alert_config.get('thresholds', {})}
            
            # Setup alert system in browser
            alert_system = await self.page.evaluate(f"""
                (thresholds) => {{
                    window.nexusUnifiedAlerts = {{
                        thresholds: thresholds,
                        alert_queue: [],
                        handlers: {{}},
                        active: true,
                        
                        checkThreshold: function(metric, value) {{
                            if (this.thresholds[metric] && value > this.thresholds[metric]) {{
                                this.alert_queue.push({{
                                    metric: metric,
                                    value: value,
                                    threshold: this.thresholds[metric],
                                    timestamp: new Date().toISOString()
                                }});
                                return true;
                            }}
                            return false;
                        }},
                        
                        getAlerts: function() {{
                            return this.alert_queue;
                        }}
                    }};
                    
                    return {{
                        success: true,
                        thresholds_configured: Object.keys(thresholds).length,
                        alert_system_active: true
                    }};
                }}
            """, thresholds)
            
            return {
                'success': True,
                'timestamp': datetime.now().isoformat(),
                'thresholds': thresholds,
                'alert_handlers': len(alert_config.get('handlers', [])),
                'browser_result': alert_system
            }
            
        except Exception as e:
            return {
                'success': False,
                'error': str(e),
                'timestamp': datetime.now().isoformat()
            }
    
    # Private monitoring methods for each type
    async def _monitor_performance(self, config: Dict[str, Any]) -> Dict[str, Any]:
        """Internal performance monitoring"""
        try:
            performance_data = await self.page.evaluate("""
                () => {
                    const perf = performance.timing;
                    const perfEntries = performance.getEntriesByType('navigation')[0];
                    const paintEntries = performance.getEntriesByType('paint');
                    
                    return {
                        timing: {
                            navigationStart: perf.navigationStart,
                            domContentLoaded: perf.domContentLoadedEventEnd - perf.domContentLoadedEventStart,
                            loadComplete: perf.loadEventEnd - perf.loadEventStart
                        },
                        navigation: perfEntries ? {
                            loadTime: perfEntries.loadEventEnd - perfEntries.loadEventStart,
                            domContentLoaded: perfEntries.domContentLoadedEventEnd - perfEntries.domContentLoadedEventStart
                        } : null,
                        paint: {
                            firstPaint: paintEntries.find(p => p.name === 'first-paint')?.startTime || 0,
                            firstContentfulPaint: paintEntries.find(p => p.name === 'first-contentful-paint')?.startTime || 0
                        },
                        memory: performance.memory ? {
                            used: performance.memory.usedJSHeapSize,
                            total: performance.memory.totalJSHeapSize,
                            limit: performance.memory.jsHeapSizeLimit
                        } : null
                    };
                }
            """)
            
            return {
                'type': 'performance',
                'data': performance_data,
                'timestamp': datetime.now().isoformat()
            }
        except Exception as e:
            return {'type': 'performance', 'error': str(e)}
    
    async def _monitor_console(self, config: Dict[str, Any]) -> Dict[str, Any]:
        """Internal console monitoring"""
        try:
            console_logs = []
            log_level = config.get('log_level', 'all')
            
            def handle_console_message(msg):
                if log_level == 'all' or msg.type == log_level:
                    console_logs.append({
                        'type': msg.type,
                        'text': msg.text,
                        'timestamp': datetime.now().isoformat()
                    })
            
            self.page.on('console', handle_console_message)
            
            # Monitor for specified duration
            await asyncio.sleep(config.get('duration', 5000) / 1000)
            
            # Remove handler
            self.page.remove_listener('console', handle_console_message)
            
            return {
                'type': 'console',
                'data': {
                    'logs': console_logs,
                    'log_count': len(console_logs),
                    'log_level': log_level
                },
                'timestamp': datetime.now().isoformat()
            }
        except Exception as e:
            return {'type': 'console', 'error': str(e)}
    
    async def _monitor_ajax(self, config: Dict[str, Any]) -> Dict[str, Any]:
        """Internal AJAX monitoring"""
        try:
            ajax_requests = []
            filter_pattern = config.get('filter_pattern')
            
            async def request_handler(request):
                if request.resource_type in ['xhr', 'fetch']:
                    url = request.url
                    if not filter_pattern or filter_pattern in url:
                        ajax_requests.append({
                            'url': url,
                            'method': request.method,
                            'resource_type': request.resource_type,
                            'timestamp': datetime.now().isoformat()
                        })
            
            self.page.on('request', request_handler)
            
            # Monitor for specified duration
            await asyncio.sleep(config.get('duration', 5000) / 1000)
            
            # Remove handler
            self.page.remove_listener('request', request_handler)
            
            return {
                'type': 'ajax',
                'data': {
                    'requests': ajax_requests,
                    'request_count': len(ajax_requests),
                    'filter_pattern': filter_pattern
                },
                'timestamp': datetime.now().isoformat()
            }
        except Exception as e:
            return {'type': 'ajax', 'error': str(e)}
    
    async def _monitor_dom_mutations(self, config: Dict[str, Any]) -> Dict[str, Any]:
        """Internal DOM mutation monitoring"""
        try:
            mutations_data = await self.page.evaluate(f"""
                (duration) => {{
                    return new Promise((resolve) => {{
                        const mutations = [];
                        
                        const observer = new MutationObserver((mutationsList) => {{
                            for (const mutation of mutationsList) {{
                                mutations.push({{
                                    type: mutation.type,
                                    target: mutation.target.tagName || 'Unknown',
                                    addedNodes: mutation.addedNodes.length,
                                    removedNodes: mutation.removedNodes.length,
                                    timestamp: new Date().toISOString()
                                }});
                            }}
                        }});
                        
                        observer.observe(document.body, {{
                            childList: true,
                            subtree: true,
                            attributes: true,
                            characterData: true
                        }});
                        
                        setTimeout(() => {{
                            observer.disconnect();
                            resolve({{
                                mutations: mutations,
                                mutation_count: mutations.length
                            }});
                        }}, duration);
                    }});
                }}
            """, config.get('duration', 5000))
            
            return {
                'type': 'dom_mutations',
                'data': mutations_data,
                'timestamp': datetime.now().isoformat()
            }
        except Exception as e:
            return {'type': 'dom_mutations', 'error': str(e)}
    
    async def _monitor_page_changes(self, config: Dict[str, Any]) -> Dict[str, Any]:
        """Internal page change monitoring"""
        try:
            # Get initial state
            initial_state = await self.page.evaluate("""
                () => ({
                    dom_length: document.documentElement.outerHTML.length,
                    element_count: document.querySelectorAll('*').length,
                    text_content: document.body.innerText,
                    title: document.title,
                    url: location.href
                })
            """)
            
            duration = config.get('duration', 5000)
            check_interval = config.get('check_interval', 1000)
            changes = []
            
            # Monitor for changes
            checks = duration // check_interval
            for i in range(checks):
                await asyncio.sleep(check_interval / 1000)
                
                current_state = await self.page.evaluate("""
                    () => ({
                        dom_length: document.documentElement.outerHTML.length,
                        element_count: document.querySelectorAll('*').length,
                        text_content: document.body.innerText,
                        title: document.title,
                        url: location.href
                    })
                """)
                
                # Check for changes
                if current_state['dom_length'] != initial_state['dom_length']:
                    changes.append({
                        'type': 'dom_size_change',
                        'old_size': initial_state['dom_length'],
                        'new_size': current_state['dom_length'],
                        'timestamp': datetime.now().isoformat()
                    })
                    initial_state['dom_length'] = current_state['dom_length']
                
                if current_state['element_count'] != initial_state['element_count']:
                    changes.append({
                        'type': 'element_count_change',
                        'old_count': initial_state['element_count'],
                        'new_count': current_state['element_count'],
                        'timestamp': datetime.now().isoformat()
                    })
                    initial_state['element_count'] = current_state['element_count']
            
            return {
                'type': 'page_changes',
                'data': {
                    'changes': changes,
                    'changes_count': len(changes),
                    'monitoring_duration': duration
                },
                'timestamp': datetime.now().isoformat()
            }
        except Exception as e:
            return {'type': 'page_changes', 'error': str(e)}

