    # NEX-051: Production-Ready Browser Methods (Lines 2501-2550)
    async def extract_page_data(self, selectors: Dict[str, str], wait_timeout: int = 5000) -> Dict[str, Any]:
        """Extract data from current page using CSS selectors"""
        if not self.page:
            return {'error': 'No active page available'}
        
        extracted_data = {}
        errors = []
        
        try:
            # Wait for page to be ready
            await self.page.wait_for_load_state('networkidle', timeout=wait_timeout)
            
            for field_name, selector in selectors.items():
                try:
                    element = await self.page.wait_for_selector(selector, timeout=wait_timeout)
                    if element:
                        # Extract text content
                        text = await element.text_content()
                        # Also get attributes if needed
                        attributes = {}
                        for attr in ['href', 'src', 'value', 'title', 'alt']:
                            attr_value = await element.get_attribute(attr)
                            if attr_value:
                                attributes[attr] = attr_value
                        
                        extracted_data[field_name] = {
                            'text': text.strip() if text else '',
                            'attributes': attributes
                        }
                    else:
                        extracted_data[field_name] = {'text': '', 'attributes': {}}
                        errors.append(f"Element not found for selector: {selector}")
                        
                except Exception as e:
                    extracted_data[field_name] = {'text': '', 'attributes': {}}
                    errors.append(f"Error extracting {field_name}: {str(e)}")
            
            return {
                'success': True,
                'data': extracted_data,
                'errors': errors,
                'timestamp': datetime.now().isoformat(),
                'url': self.page.url if self.page else 'unknown'
            }
            
        except Exception as e:
            return {
                'success': False,
                'error': f"Page data extraction failed: {str(e)}",
                'timestamp': datetime.now().isoformat()
            }

    async def take_screenshot(self, full_page: bool = True, path: Optional[str] = None) -> Dict[str, Any]:
        """Take screenshot of current page"""
        if not self.page:
            return {'error': 'No active page available'}
        
        try:
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            screenshot_path = path or f"screenshot_{timestamp}.png"
            
            await self.page.screenshot(
                path=screenshot_path,
                full_page=full_page
            )
            
            return {
                'success': True,
                'path': screenshot_path,
                'timestamp': timestamp,
                'url': self.page.url,
                'full_page': full_page
            }
            
        except Exception as e:
            return {
                'success': False,
                'error': f"Screenshot failed: {str(e)}",
                'timestamp': datetime.now().isoformat()
            }

    async def fill_form_fields(self, form_data: Dict[str, str], submit: bool = False) -> Dict[str, Any]:
        """Fill form fields on current page"""
        if not self.page:
            return {'error': 'No active page available'}
        
        filled_fields = []
        errors = []
        
        try:
            for field_selector, value in form_data.items():
                try:
                    # Wait for field to be available
                    await self.page.wait_for_selector(field_selector, timeout=5000)
                    
                    # Fill the field
                    await self.page.fill(field_selector, value)
                    filled_fields.append(field_selector)
                    
                except Exception as e:
                    errors.append(f"Failed to fill {field_selector}: {str(e)}")
            
            # Submit form if requested
            submit_result = None
            if submit:
                try:
                    # Look for submit button or form
                    submit_selectors = [
                        'button[type="submit"]',
                        'input[type="submit"]',
                        'button:has-text("Submit")',
                        'button:has-text("Send")',
                        'form'
                    ]
                    
                    for selector in submit_selectors:
                        try:
                            await self.page.click(selector, timeout=2000)
                            submit_result = f"Submitted via {selector}"
                            break
                        except:
                            continue
                    
                    if not submit_result:
                        submit_result = "No submit element found"
                        
                except Exception as e:
                    submit_result = f"Submit failed: {str(e)}"
            
            return {
                'success': True,
                'filled_fields': filled_fields,
                'errors': errors,
                'submit_result': submit_result,
                'timestamp': datetime.now().isoformat(),
                'url': self.page.url
            }
            
        except Exception as e:
            return {
                'success': False,
                'error': f"Form filling failed: {str(e)}",
                'timestamp': datetime.now().isoformat()
            }

    async def wait_and_click(self, selector: str, timeout: int = 10000) -> Dict[str, Any]:
        """Wait for element and click it"""
        if not self.page:
            return {'error': 'No active page available'}
        
        try:
            # Wait for element
            element = await self.page.wait_for_selector(selector, timeout=timeout)
            
            if element:
                # Scroll into view
                await element.scroll_into_view_if_needed()
                
                # Click element
                await element.click()
                
                return {
                    'success': True,
                    'selector': selector,
                    'timestamp': datetime.now().isoformat(),
                    'url': self.page.url
                }
            else:
                return {
                    'success': False,
                    'error': f"Element not found: {selector}",
                    'timestamp': datetime.now().isoformat()
                }
                
        except Exception as e:
            return {
                'success': False,
                'error': f"Click failed: {str(e)}",
                'selector': selector,
                'timestamp': datetime.now().isoformat()
            }

    async def get_page_info(self) -> Dict[str, Any]:
        """Get comprehensive information about current page"""
        if not self.page:
            return {'error': 'No active page available'}
        
        try:
            # Get basic page info
            title = await self.page.title()
            url = self.page.url
            
            # Get meta information
            meta_description = await self.page.get_attribute('meta[name="description"]', 'content') or ''
            meta_keywords = await self.page.get_attribute('meta[name="keywords"]', 'content') or ''
            
            # Count elements
            links_count = await self.page.locator('a').count()
            images_count = await self.page.locator('img').count()
            forms_count = await self.page.locator('form').count()
            inputs_count = await self.page.locator('input').count()
            
            # Get all links
            links = []
            for i in range(min(links_count, 20)):  # Limit to first 20 links
                try:
                    link = self.page.locator('a').nth(i)
                    href = await link.get_attribute('href')
                    text = await link.text_content()
                    if href:
                        links.append({'href': href, 'text': text.strip() if text else ''})
                except:
                    continue
            
            return {
                'success': True,
                'title': title,
                'url': url,
                'meta': {
                    'description': meta_description,
                    'keywords': meta_keywords
                },
                'elements': {
                    'links': links_count,
                    'images': images_count,
                    'forms': forms_count,
                    'inputs': inputs_count
                },
                'links_sample': links,
                'timestamp': datetime.now().isoformat()
            }
            
        except Exception as e:
            return {
                'success': False,
                'error': f"Failed to get page info: {str(e)}",
                'timestamp': datetime.now().isoformat()
            }

    async def save_page_content(self, format: str = 'html', path: Optional[str] = None) -> Dict[str, Any]:
        """Save page content in various formats"""
        if not self.page:
            return {'error': 'No active page available'}
        
        try:
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            
            if format.lower() == 'pdf':
                file_path = path or f"page_{timestamp}.pdf"
                await self.page.pdf(path=file_path, format='A4')
            elif format.lower() == 'html':
                file_path = path or f"page_{timestamp}.html"
                content = await self.page.content()
                with open(file_path, 'w', encoding='utf-8') as f:
                    f.write(content)
            else:
                return {'error': f'Unsupported format: {format}. Use "html" or "pdf"'}
            
            return {
                'success': True,
                'path': file_path,
                'format': format,
                'timestamp': timestamp,
                'url': self.page.url,
                'file_size': os.path.getsize(file_path) if os.path.exists(file_path) else 0
            }
            
        except Exception as e:
            return {
                'success': False,
                'error': f"Save failed: {str(e)}",
                'format': format,
                'timestamp': datetime.now().isoformat()
            }

    # NEX-052: Advanced Browser Automation Methods (Lines 2551-2600)
    async def extract_table_data(self, table_selector: str = 'table', include_headers: bool = True) -> Dict[str, Any]:
        """Extract structured data from HTML tables"""
        if not self.page:
            return {'error': 'No active page available'}
        
        try:
            tables = await self.page.locator(table_selector).all()
            if not tables:
                return {'error': f'No tables found with selector: {table_selector}'}
            
            extracted_tables = []
            
            for table_index, table in enumerate(tables):
                table_data = {
                    'table_index': table_index,
                    'headers': [],
                    'rows': []
                }
                
                # Extract headers if requested
                if include_headers:
                    headers = await table.locator('th').all()
                    for header in headers:
                        header_text = await header.text_content()
                        table_data['headers'].append(header_text.strip() if header_text else '')
                
                # Extract rows
                rows = await table.locator('tr').all()
                for row in rows:
                    cells = await row.locator('td').all()
                    if cells:  # Only process rows with td cells (not header rows)
                        row_data = []
                        for cell in cells:
                            cell_text = await cell.text_content()
                            row_data.append(cell_text.strip() if cell_text else '')
                        table_data['rows'].append(row_data)
                
                extracted_tables.append(table_data)
            
            return {
                'success': True,
                'tables': extracted_tables,
                'table_count': len(extracted_tables),
                'timestamp': datetime.now().isoformat(),
                'url': self.page.url
            }
            
        except Exception as e:
            return {
                'success': False,
                'error': f"Table extraction failed: {str(e)}",
                'timestamp': datetime.now().isoformat()
            }

    async def wait_for_navigation(self, trigger_action: Callable, timeout: int = 30000) -> Dict[str, Any]:
        """Wait for page navigation after triggering an action"""
        if not self.page:
            return {'error': 'No active page available'}
        
        try:
            initial_url = self.page.url
            
            # Set up navigation promise
            async with self.page.expect_navigation(timeout=timeout):
                # Execute the trigger action
                await trigger_action()
            
            final_url = self.page.url
            
            return {
                'success': True,
                'initial_url': initial_url,
                'final_url': final_url,
                'navigation_occurred': initial_url != final_url,
                'timestamp': datetime.now().isoformat()
            }
            
        except Exception as e:
            return {
                'success': False,
                'error': f"Navigation wait failed: {str(e)}",
                'initial_url': initial_url if 'initial_url' in locals() else 'unknown',
                'timestamp': datetime.now().isoformat()
            }

    async def handle_dialog(self, dialog_action: str = 'accept', prompt_text: str = '') -> Dict[str, Any]:
        """Handle JavaScript dialogs (alert, confirm, prompt)"""
        if not self.page:
            return {'error': 'No active page available'}
        
        try:
            dialog_handled = False
            dialog_message = ''
            
            # Set up dialog handler
            async def dialog_handler(dialog):
                nonlocal dialog_handled, dialog_message
                dialog_handled = True
                dialog_message = dialog.message
                
                if dialog_action == 'accept':
                    if dialog.type == 'prompt':
                        await dialog.accept(prompt_text)
                    else:
                        await dialog.accept()
                elif dialog_action == 'dismiss':
                    await dialog.dismiss()
                else:
                    await dialog.accept()  # Default to accept
            
            self.page.on('dialog', dialog_handler)
            
            # Give some time for dialog to appear and be handled
            await asyncio.sleep(1)
            
            return {
                'success': True,
                'dialog_handled': dialog_handled,
                'dialog_message': dialog_message,
                'action_taken': dialog_action,
                'prompt_text_used': prompt_text if dialog_action == 'accept' else None,
                'timestamp': datetime.now().isoformat()
            }
            
        except Exception as e:
            return {
                'success': False,
                'error': f"Dialog handling failed: {str(e)}",
                'timestamp': datetime.now().isoformat()
            }
        finally:
            # Remove dialog handler
            try:
                self.page.remove_listener('dialog', dialog_handler)
            except:
                pass

    async def scroll_to_element(self, selector: str, behavior: str = 'smooth') -> Dict[str, Any]:
        """Scroll to a specific element on the page"""
        if not self.page:
            return {'error': 'No active page available'}
        
        try:
            element = await self.page.wait_for_selector(selector, timeout=10000)
            
            if element:
                # Scroll element into view
                await element.scroll_into_view_if_needed()
                
                # Get element position for verification
                bounding_box = await element.bounding_box()
                
                return {
                    'success': True,
                    'selector': selector,
                    'element_position': bounding_box,
                    'scroll_behavior': behavior,
                    'timestamp': datetime.now().isoformat(),
                    'url': self.page.url
                }
            else:
                return {
                    'success': False,
                    'error': f"Element not found: {selector}",
                    'timestamp': datetime.now().isoformat()
                }
                
        except Exception as e:
            return {
                'success': False,
                'error': f"Scroll to element failed: {str(e)}",
                'selector': selector,
                'timestamp': datetime.now().isoformat()
            }

    async def get_element_attributes(self, selector: str, attributes: List[str] = None) -> Dict[str, Any]:
        """Get specific attributes from an element"""
        if not self.page:
            return {'error': 'No active page available'}
        
        if attributes is None:
            attributes = ['id', 'class', 'href', 'src', 'alt', 'title', 'value', 'type']
        
        try:
            element = await self.page.wait_for_selector(selector, timeout=10000)
            
            if element:
                element_attributes = {}
                
                # Get requested attributes
                for attr in attributes:
                    attr_value = await element.get_attribute(attr)
                    if attr_value is not None:
                        element_attributes[attr] = attr_value
                
                # Get text content
                text_content = await element.text_content()
                inner_html = await element.inner_html()
                
                return {
                    'success': True,
                    'selector': selector,
                    'attributes': element_attributes,
                    'text_content': text_content.strip() if text_content else '',
                    'inner_html': inner_html,
                    'timestamp': datetime.now().isoformat(),
                    'url': self.page.url
                }
            else:
                return {
                    'success': False,
                    'error': f"Element not found: {selector}",
                    'timestamp': datetime.now().isoformat()
                }
                
        except Exception as e:
            return {
                'success': False,
                'error': f"Get element attributes failed: {str(e)}",
                'selector': selector,
                'timestamp': datetime.now().isoformat()
            }

    async def execute_javascript(self, script: str, *args) -> Dict[str, Any]:
        """Execute JavaScript code on the current page"""
        if not self.page:
            return {'error': 'No active page available'}
        
        try:
            # Execute the JavaScript
            result = await self.page.evaluate(script, *args)
            
            return {
                'success': True,
                'script': script,
                'arguments': list(args),
                'result': result,
                'result_type': type(result).__name__,
                'timestamp': datetime.now().isoformat(),
                'url': self.page.url
            }
            
        except Exception as e:
            return {
                'success': False,
                'error': f"JavaScript execution failed: {str(e)}",
                'script': script,
                'arguments': list(args),
                'timestamp': datetime.now().isoformat()
            }

