    async def manage_cookies(self, action: str, domain: Optional[str] = None, 
                           cookies: Optional[List[Dict[str, Any]]] = None) -> Dict[str, Any]:
        """
        Advanced cookie management for browser sessions
        
        Args:
            action: Action to perform ('get', 'set', 'delete', 'clear')
            domain: Target domain for cookie operations
            cookies: List of cookie objects to set
        
        Returns:
            Dict with operation results and cookie data
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            result = {
                'success': True,
                'action': action,
                'domain': domain,
                'timestamp': datetime.now().isoformat()
            }

            if action == 'get':
                # Get all cookies or cookies for specific domain
                all_cookies = await self.page.context.cookies(domain)
                result['cookies'] = all_cookies
                result['count'] = len(all_cookies)

            elif action == 'set' and cookies:
                # Set cookies
                await self.page.context.add_cookies(cookies)
                result['cookies_set'] = len(cookies)

            elif action == 'delete' and domain:
                # Delete cookies for domain
                await self.page.context.clear_cookies(domain=domain)
                result['domain_cleared'] = domain

            elif action == 'clear':
                # Clear all cookies
                await self.page.context.clear_cookies()
                result['all_cookies_cleared'] = True

            else:
                result['success'] = False
                result['error'] = f'Invalid action or missing parameters for: {action}'

            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Cookie management failed: {str(e)}',
                'action': action,
                'timestamp': datetime.now().isoformat()
            }

    async def configure_proxy(self, proxy_config: Optional[Dict[str, str]] = None) -> Dict[str, Any]:
        """
        Configure proxy settings for browser context
        
        Args:
            proxy_config: Proxy configuration dict with server, username, password
        
        Returns:
            Dict with proxy configuration status
        """
        try:
            result = {
                'success': True,
                'timestamp': datetime.now().isoformat()
            }

            if proxy_config:
                # Note: Proxy must be set when creating browser context
                # This method documents current proxy or prepares for next session
                result['proxy_config'] = {
                    'server': proxy_config.get('server', 'Not configured'),
                    'has_auth': bool(proxy_config.get('username')),
                    'configured_for_next_session': True
                }
                
                # Store for next browser session
                self._next_proxy_config = proxy_config
                
            else:
                result['proxy_config'] = {
                    'server': 'Direct connection',
                    'has_auth': False,
                    'configured': False
                }

            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Proxy configuration failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

