    async def manage_browser_storage(self, storage_type: str, action: str, 
                                   key: Optional[str] = None, value: Optional[str] = None) -> Dict[str, Any]:
        """
        Manage browser storage (localStorage, sessionStorage)
        
        Args:
            storage_type: Type of storage ('local' or 'session')
            action: Action to perform ('get', 'set', 'remove', 'clear', 'list')
            key: Storage key for get/set/remove operations
            value: Value to set for 'set' operation
        
        Returns:
            Dict with storage operation results
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            storage_obj = f"{storage_type}Storage" if storage_type in ['local', 'session'] else None
            if not storage_obj:
                return {
                    'success': False,
                    'error': f'Invalid storage type: {storage_type}',
                    'timestamp': datetime.now().isoformat()
                }

            result = {
                'success': True,
                'storage_type': storage_type,
                'action': action,
                'timestamp': datetime.now().isoformat()
            }

            if action == 'get' and key:
                value = await self.page.evaluate(f"() => {storage_obj}.getItem('{key}')")
                result['key'] = key
                result['value'] = value

            elif action == 'set' and key and value:
                await self.page.evaluate(f"() => {storage_obj}.setItem('{key}', '{value}')")
                result['key'] = key
                result['value'] = value

            elif action == 'remove' and key:
                await self.page.evaluate(f"() => {storage_obj}.removeItem('{key}')")
                result['key'] = key
                result['removed'] = True

            elif action == 'clear':
                await self.page.evaluate(f"() => {storage_obj}.clear()")
                result['cleared'] = True

            elif action == 'list':
                keys = await self.page.evaluate(f"""
                    () => {{
                        let keys = [];
                        for (let i = 0; i < {storage_obj}.length; i++) {{
                            keys.push({storage_obj}.key(i));
                        }}
                        return keys;
                    }}
                """)
                result['keys'] = keys
                result['count'] = len(keys) if keys else 0

            else:
                result['success'] = False
                result['error'] = f'Invalid action or missing parameters for: {action}'

            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Storage management failed: {str(e)}',
                'storage_type': storage_type,
                'action': action,
                'timestamp': datetime.now().isoformat()
            }

    async def capture_network_traffic(self, enable: bool = True, filter_types: Optional[List[str]] = None) -> Dict[str, Any]:
        """
        Capture and analyze network traffic
        
        Args:
            enable: Whether to enable network traffic capture
            filter_types: List of resource types to filter ('document', 'stylesheet', 'image', 'script', 'xhr', 'fetch')
        
        Returns:
            Dict with network traffic capture status and data
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            result = {
                'success': True,
                'enabled': enable,
                'timestamp': datetime.now().isoformat()
            }

            if enable:
                # Initialize traffic capture storage if not exists
                if not hasattr(self, '_network_traffic'):
                    self._network_traffic = []

                # Set up network request monitoring
                async def track_request(request):
                    request_data = {
                        'url': request.url,
                        'method': request.method,
                        'resource_type': request.resource_type,
                        'headers': dict(request.headers),
                        'timestamp': datetime.now().isoformat()
                    }
                    
                    if not filter_types or request.resource_type in filter_types:
                        self._network_traffic.append(request_data)

                # Set up network response monitoring
                async def track_response(response):
                    response_data = {
                        'url': response.url,
                        'status': response.status,
                        'headers': dict(response.headers),
                        'size': len(await response.body()) if response.status < 400 else 0,
                        'timestamp': datetime.now().isoformat()
                    }
                    
                    # Find corresponding request and add response data
                    for traffic in reversed(self._network_traffic):
                        if traffic['url'] == response.url and 'response' not in traffic:
                            traffic['response'] = response_data
                            break

                self.page.on('request', track_request)
                self.page.on('response', track_response)
                
                result['capture_started'] = True
                result['filter_types'] = filter_types or ['all']
                
            else:
                # Disable monitoring and return captured data
                if hasattr(self, '_network_traffic'):
                    result['captured_requests'] = len(self._network_traffic)
                    result['traffic_data'] = self._network_traffic[-10:]  # Last 10 requests
                    result['capture_stopped'] = True
                else:
                    result['captured_requests'] = 0

            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Network traffic capture failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

    # ==============================================================================
    # NEX-054: Production Web Scraping & Accessibility Features
    # ==============================================================================

    async def extract_structured_data(self, schema: Dict[str, Any], 
                                     wait_timeout: int = 5000) -> Dict[str, Any]:
        """
        Extract structured data from web pages using defined schema
        
        Args:
            schema: Data extraction schema with selectors and transformations
            wait_timeout: Maximum time to wait for elements
        
        Returns:
            Dict with extracted structured data
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            result = {
                'success': True,
                'url': self.page.url,
                'timestamp': datetime.now().isoformat(),
                'data': {}
            }

            for field_name, field_config in schema.items():
                try:
                    selector = field_config.get('selector')
                    attribute = field_config.get('attribute', 'textContent')
                    multiple = field_config.get('multiple', False)
                    transform = field_config.get('transform')

                    if multiple:
                        # Extract multiple elements
                        elements = await self.page.query_selector_all(selector)
                        values = []
                        for element in elements:
                            if attribute == 'textContent':
                                value = await element.text_content()
                            elif attribute == 'innerHTML':
                                value = await element.inner_html()
                            else:
                                value = await element.get_attribute(attribute)
                            
                            if transform and value:
                                if transform == 'strip':
                                    value = value.strip()
                                elif transform == 'lower':
                                    value = value.lower()
                                elif transform == 'int':
                                    try:
                                        value = int(value)
                                    except ValueError:
                                        pass
                                elif transform == 'float':
                                    try:
                                        value = float(value)
                                    except ValueError:
                                        pass
                            
                            values.append(value)
                        result['data'][field_name] = values
                    else:
                        # Extract single element
                        element = await self.page.wait_for_selector(selector, timeout=wait_timeout)
                        if element:
                            if attribute == 'textContent':
                                value = await element.text_content()
                            elif attribute == 'innerHTML':
                                value = await element.inner_html()
                            else:
                                value = await element.get_attribute(attribute)

                            if transform and value:
                                if transform == 'strip':
                                    value = value.strip()
                                elif transform == 'lower':
                                    value = value.lower()
                                elif transform == 'int':
                                    try:
                                        value = int(value)
                                    except ValueError:
                                        pass
                                elif transform == 'float':
                                    try:
                                        value = float(value)
                                    except ValueError:
                                        pass

                            result['data'][field_name] = value
                        else:
                            result['data'][field_name] = None

                except Exception as field_error:
                    result['data'][field_name] = {
                        'error': str(field_error),
                        'field_config': field_config
                    }

            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Structured data extraction failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

