    async def check_accessibility(self, run_audit: bool = True) -> Dict[str, Any]:
        """
        Check web page accessibility and WCAG compliance
        
        Args:
            run_audit: Whether to run comprehensive accessibility audit
        
        Returns:
            Dict with accessibility analysis results
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            result = {
                'success': True,
                'url': self.page.url,
                'timestamp': datetime.now().isoformat()
            }

            if run_audit:
                # Check for common accessibility issues
                accessibility_checks = await self.page.evaluate("""
                    () => {
                        const issues = [];
                        
                        // Check for images without alt text
                        const images = document.querySelectorAll('img');
                        let imagesWithoutAlt = 0;
                        images.forEach(img => {
                            if (!img.alt || img.alt.trim() === '') {
                                imagesWithoutAlt++;
                            }
                        });
                        
                        // Check for form inputs without labels
                        const inputs = document.querySelectorAll('input[type="text"], input[type="email"], input[type="password"], textarea');
                        let inputsWithoutLabels = 0;
                        inputs.forEach(input => {
                            const id = input.id;
                            const label = id ? document.querySelector(`label[for="${id}"]`) : null;
                            const ariaLabel = input.getAttribute('aria-label');
                            const ariaLabelledby = input.getAttribute('aria-labelledby');
                            
                            if (!label && !ariaLabel && !ariaLabelledby) {
                                inputsWithoutLabels++;
                            }
                        });
                        
                        // Check for headings structure
                        const headings = document.querySelectorAll('h1, h2, h3, h4, h5, h6');
                        const headingLevels = Array.from(headings).map(h => parseInt(h.tagName.charAt(1)));
                        
                        // Check color contrast (basic)
                        const elementsWithBackground = document.querySelectorAll('*');
                        let lowContrastElements = 0;
                        
                        return {
                            totalImages: images.length,
                            imagesWithoutAlt: imagesWithoutAlt,
                            totalInputs: inputs.length,
                            inputsWithoutLabels: inputsWithoutLabels,
                            totalHeadings: headings.length,
                            headingLevels: headingLevels,
                            hasH1: headingLevels.includes(1),
                            lowContrastElements: lowContrastElements
                        };
                    }
                """)

                result['accessibility_audit'] = accessibility_checks
                
                # Calculate accessibility score
                total_issues = (accessibility_checks.get('imagesWithoutAlt', 0) + 
                              accessibility_checks.get('inputsWithoutLabels', 0))
                total_elements = (accessibility_checks.get('totalImages', 0) + 
                                accessibility_checks.get('totalInputs', 0))
                
                if total_elements > 0:
                    score = max(0, (total_elements - total_issues) / total_elements * 100)
                    result['accessibility_score'] = round(score, 2)
                else:
                    result['accessibility_score'] = 100

            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Accessibility check failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

    async def debug_page_issues(self, check_console: bool = True) -> Dict[str, Any]:
        """
        Debug common web page issues and errors
        
        Args:
            check_console: Whether to capture console errors
        
        Returns:
            Dict with debugging information
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            result = {
                'success': True,
                'url': self.page.url,
                'timestamp': datetime.now().isoformat()
            }

            # Get page info
            page_info = await self.page.evaluate("""
                () => {
                    return {
                        title: document.title,
                        doctype: document.doctype ? document.doctype.name : 'none',
                        lang: document.documentElement.lang || 'not set',
                        charset: document.characterSet,
                        readyState: document.readyState,
                        url: window.location.href,
                        protocol: window.location.protocol,
                        host: window.location.host
                    };
                }
            """)
            result['page_info'] = page_info

            # Check for broken links and images
            broken_resources = await self.page.evaluate("""
                async () => {
                    const brokenLinks = [];
                    const brokenImages = [];
                    
                    // Check images
                    const images = document.querySelectorAll('img');
                    images.forEach(img => {
                        if (!img.complete || img.naturalWidth === 0) {
                            brokenImages.push({
                                src: img.src,
                                alt: img.alt || 'No alt text'
                            });
                        }
                    });
                    
                    return {
                        brokenImages: brokenImages,
                        totalImages: images.length,
                        totalLinks: document.querySelectorAll('a[href]').length
                    };
                }
            """)
            result['broken_resources'] = broken_resources

            # Performance metrics
            performance_metrics = await self.page.evaluate("""
                () => {
                    const perf = performance.timing;
                    return {
                        loadTime: perf.loadEventEnd - perf.navigationStart,
                        domReady: perf.domContentLoadedEventEnd - perf.navigationStart,
                        resourceCount: performance.getEntriesByType('resource').length,
                        navigationTiming: {
                            dns: perf.domainLookupEnd - perf.domainLookupStart,
                            tcp: perf.connectEnd - perf.connectStart,
                            ttfb: perf.responseStart - perf.requestStart
                        }
                    };
                }
            """)
            result['performance'] = performance_metrics

            if check_console:
                # Capture console errors (would need to be set up during page load)
                result['console_monitoring'] = 'Console error capture requires setup during page initialization'

            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Page debugging failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

    async def batch_url_processor(self, urls: List[str], 
                                 action_callback: Optional[Callable] = None,
                                 max_concurrent: int = 3) -> Dict[str, Any]:
        """
        Process multiple URLs in batches with optional custom actions
        
        Args:
            urls: List of URLs to process
            action_callback: Optional callback function to run on each page
            max_concurrent: Maximum concurrent pages to process
        
        Returns:
            Dict with batch processing results
        """
        if not self.browser:
            return {
                'success': False,
                'error': 'No browser instance available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            import asyncio
            from datetime import datetime
            
            result = {
                'success': True,
                'total_urls': len(urls),
                'processed': 0,
                'failed': 0,
                'results': [],
                'timestamp': datetime.now().isoformat()
            }

            async def process_single_url(url: str, semaphore) -> Dict[str, Any]:
                async with semaphore:
                    try:
                        # Create new page for this URL
                        page = await self.browser.new_page()
                        await page.goto(url)
                        
                        page_result = {
                            'url': url,
                            'success': True,
                            'title': await page.title(),
                            'status': 'processed'
                        }

                        # Run custom callback if provided
                        if action_callback and callable(action_callback):
                            try:
                                callback_result = await action_callback(page)
                                page_result['callback_result'] = callback_result
                            except Exception as callback_error:
                                page_result['callback_error'] = str(callback_error)

                        await page.close()
                        return page_result

                    except Exception as e:
                        return {
                            'url': url,
                            'success': False,
                            'error': str(e),
                            'status': 'failed'
                        }

            # Create semaphore to limit concurrent processing
            semaphore = asyncio.Semaphore(max_concurrent)
            
            # Process URLs
            tasks = [process_single_url(url, semaphore) for url in urls]
            results = await asyncio.gather(*tasks, return_exceptions=True)

            # Compile results
            for url_result in results:
                if isinstance(url_result, Exception):
                    result['failed'] += 1
                    result['results'].append({
                        'url': 'unknown',
                        'success': False,
                        'error': str(url_result),
                        'status': 'exception'
                    })
                else:
                    if url_result.get('success'):
                        result['processed'] += 1
                    else:
                        result['failed'] += 1
                    result['results'].append(url_result)

            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Batch URL processing failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

    async def generate_page_report(self, include_screenshots: bool = False) -> Dict[str, Any]:
        """
        Generate comprehensive page analysis report
        
        Args:
            include_screenshots: Whether to include screenshots in report
        
        Returns:
            Dict with comprehensive page report
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            report = {
                'success': True,
                'url': self.page.url,
                'timestamp': datetime.now().isoformat(),
                'analysis': {}
            }

            # Get basic page info
            report['analysis']['basic_info'] = await self.get_page_info()
            
            # Get performance metrics
            report['analysis']['performance'] = await self.monitor_performance()
            
            # Get accessibility analysis
            report['analysis']['accessibility'] = await self.check_accessibility()
            
            # Get debugging info
            report['analysis']['debug_info'] = await self.debug_page_issues()

            # Take screenshot if requested
            if include_screenshots:
                screenshot_result = await self.take_screenshot(path=f"report_screenshot_{int(datetime.now().timestamp())}.png")
                report['analysis']['screenshot'] = screenshot_result

            # Calculate overall health score
            accessibility_score = report['analysis']['accessibility'].get('accessibility_score', 0)
            performance_score = 100  # Simplified - would need more complex calculation
            has_errors = len(report['analysis']['debug_info'].get('broken_resources', {}).get('brokenImages', [])) > 0
            
            overall_score = (accessibility_score + performance_score) / 2
            if has_errors:
                overall_score *= 0.9  # Penalty for errors
                
            report['overall_health_score'] = round(overall_score, 2)

            return report

        except Exception as e:
            return {
                'success': False,
                'error': f'Page report generation failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

