    async def wait_for_condition(self, condition_func: Callable, 
                                timeout: int = 30000, interval: int = 1000) -> Dict[str, Any]:
        """
        Wait for a custom condition to be met on the page
        
        Args:
            condition_func: Function that returns True when condition is met
            timeout: Maximum time to wait in milliseconds
            interval: Check interval in milliseconds
        
        Returns:
            Dict with condition waiting results
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            import asyncio
            
            start_time = datetime.now()
            end_time = start_time.timestamp() * 1000 + timeout
            
            while datetime.now().timestamp() * 1000 < end_time:
                try:
                    # Execute condition function
                    if await condition_func(self.page):
                        return {
                            'success': True,
                            'condition_met': True,
                            'wait_time': (datetime.now() - start_time).total_seconds() * 1000,
                            'timestamp': datetime.now().isoformat()
                        }
                except Exception as condition_error:
                    # Continue waiting if condition function fails
                    pass
                
                await asyncio.sleep(interval / 1000)
            
            # Timeout reached
            return {
                'success': False,
                'condition_met': False,
                'timeout_reached': True,
                'wait_time': timeout,
                'timestamp': datetime.now().isoformat()
            }

        except Exception as e:
            return {
                'success': False,
                'error': f'Condition waiting failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

    async def intercept_network_requests(self, enable: bool = True, 
                                       patterns: Optional[List[str]] = None,
                                       modify_responses: bool = False) -> Dict[str, Any]:
        """
        Intercept and optionally modify network requests
        
        Args:
            enable: Whether to enable request interception
            patterns: URL patterns to intercept (supports wildcards)
            modify_responses: Whether to enable response modification
        
        Returns:
            Dict with interception configuration results
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            result = {
                'success': True,
                'enabled': enable,
                'patterns': patterns or [],
                'modify_responses': modify_responses,
                'timestamp': datetime.now().isoformat()
            }

            if enable:
                # Enable request interception
                await self.page.route("**/*", self._handle_intercepted_request)
                
                # Store interception config
                self._interception_config = {
                    'patterns': patterns or [],
                    'modify_responses': modify_responses,
                    'intercepted_requests': []
                }
                
                result['interception_enabled'] = True
                
            else:
                # Disable request interception
                await self.page.unroute("**/*")
                result['interception_disabled'] = True
                
                # Return captured data if available
                if hasattr(self, '_interception_config'):
                    result['captured_requests'] = len(self._interception_config.get('intercepted_requests', []))

            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Request interception failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

    async def _handle_intercepted_request(self, route, request):
        """Internal method to handle intercepted requests"""
        try:
            # Store request info
            if hasattr(self, '_interception_config'):
                self._interception_config['intercepted_requests'].append({
                    'url': request.url,
                    'method': request.method,
                    'headers': dict(request.headers),
                    'timestamp': datetime.now().isoformat()
                })
            
            # Continue with request (could be modified here)
            await route.continue_()
            
        except Exception:
            # Fallback to continue request
            await route.continue_()

    async def simulate_user_interactions(self, actions: List[Dict[str, Any]]) -> Dict[str, Any]:
        """
        Simulate realistic user interactions with timing and randomization
        
        Args:
            actions: List of action dictionaries with type, target, and options
        
        Returns:
            Dict with interaction simulation results
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            import asyncio
            import random
            
            result = {
                'success': True,
                'total_actions': len(actions),
                'completed_actions': 0,
                'failed_actions': 0,
                'results': [],
                'timestamp': datetime.now().isoformat()
            }

            for i, action in enumerate(actions):
                try:
                    action_type = action.get('type')
                    target = action.get('target')
                    options = action.get('options', {})
                    
                    # Add realistic delays
                    delay = options.get('delay', random.randint(500, 2000))
                    await asyncio.sleep(delay / 1000)
                    
                    action_result = {
                        'action_index': i,
                        'type': action_type,
                        'target': target,
                        'success': False
                    }

                    if action_type == 'click':
                        element = await self.page.wait_for_selector(target, timeout=5000)
                        if element:
                            await element.click()
                            action_result['success'] = True
                            
                    elif action_type == 'type':
                        text = options.get('text', '')
                        element = await self.page.wait_for_selector(target, timeout=5000)
                        if element:
                            # Clear existing text
                            await element.click()
                            await self.page.keyboard.press('Control+A')
                            # Type with realistic speed
                            for char in text:
                                await self.page.keyboard.type(char)
                                await asyncio.sleep(random.randint(50, 150) / 1000)
                            action_result['success'] = True
                            action_result['text'] = text
                            
                    elif action_type == 'scroll':
                        scroll_y = options.get('y', 500)
                        await self.page.evaluate(f"window.scrollBy(0, {scroll_y})")
                        action_result['success'] = True
                        action_result['scroll_y'] = scroll_y
                        
                    elif action_type == 'hover':
                        element = await self.page.wait_for_selector(target, timeout=5000)
                        if element:
                            await element.hover()
                            action_result['success'] = True
                            
                    elif action_type == 'wait':
                        wait_time = options.get('time', 1000)
                        await asyncio.sleep(wait_time / 1000)
                        action_result['success'] = True
                        action_result['wait_time'] = wait_time

                    if action_result['success']:
                        result['completed_actions'] += 1
                    else:
                        result['failed_actions'] += 1
                        
                    result['results'].append(action_result)

                except Exception as action_error:
                    result['failed_actions'] += 1
                    result['results'].append({
                        'action_index': i,
                        'type': action_type,
                        'target': target,
                        'success': False,
                        'error': str(action_error)
                    })

            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'User interaction simulation failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

    async def test_form_validation(self, form_selector: str, 
                                 test_cases: List[Dict[str, Any]]) -> Dict[str, Any]:
        """
        Test form validation with various input scenarios
        
        Args:
            form_selector: CSS selector for the form element
            test_cases: List of test case dictionaries
        
        Returns:
            Dict with form validation test results
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            result = {
                'success': True,
                'form_selector': form_selector,
                'total_test_cases': len(test_cases),
                'passed': 0,
                'failed': 0,
                'results': [],
                'timestamp': datetime.now().isoformat()
            }

            # Verify form exists
            form = await self.page.wait_for_selector(form_selector, timeout=5000)
            if not form:
                return {
                    'success': False,
                    'error': f'Form not found: {form_selector}',
                    'timestamp': datetime.now().isoformat()
                }

            for i, test_case in enumerate(test_cases):
                try:
                    test_result = {
                        'test_case_index': i,
                        'name': test_case.get('name', f'Test case {i}'),
                        'inputs': test_case.get('inputs', {}),
                        'expected': test_case.get('expected', {}),
                        'success': False
                    }

                    # Fill form inputs
                    for field_selector, value in test_case.get('inputs', {}).items():
                        field = await self.page.wait_for_selector(field_selector, timeout=3000)
                        if field:
                            await field.fill(str(value))

                    # Submit form
                    submit_button = test_case.get('submit_selector', f'{form_selector} button[type="submit"]')
                    submit_element = await self.page.wait_for_selector(submit_button, timeout=3000)
                    if submit_element:
                        await submit_element.click()

                    # Check validation results
                    await self.page.wait_for_timeout(1000)  # Wait for validation
                    
                    validation_passed = True
                    validation_results = {}
                    
                    # Check expected validation messages
                    for field, expected_message in test_case.get('expected', {}).items():
                        validation_selector = f'{field}_error'  # Customize as needed
                        try:
                            validation_element = await self.page.wait_for_selector(
                                validation_selector, timeout=1000
                            )
                            if validation_element:
                                actual_message = await validation_element.text_content()
                                validation_results[field] = {
                                    'expected': expected_message,
                                    'actual': actual_message,
                                    'matches': expected_message in actual_message
                                }
                                if not validation_results[field]['matches']:
                                    validation_passed = False
                            else:
                                validation_results[field] = {
                                    'expected': expected_message,
                                    'actual': None,
                                    'matches': False
                                }
                                validation_passed = False
                        except:
                            validation_results[field] = {
                                'expected': expected_message,
                                'actual': None,
                                'matches': False
                            }
                            validation_passed = False

                    test_result['validation_results'] = validation_results
                    test_result['success'] = validation_passed
                    
                    if validation_passed:
                        result['passed'] += 1
                    else:
                        result['failed'] += 1
                        
                    result['results'].append(test_result)

                except Exception as test_error:
                    result['failed'] += 1
                    result['results'].append({
                        'test_case_index': i,
                        'name': test_case.get('name', f'Test case {i}'),
                        'success': False,
                        'error': str(test_error)
                    })

            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Form validation testing failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

    async def compare_page_states(self, state1_actions: List[Dict[str, Any]], 
                                state2_actions: List[Dict[str, Any]]) -> Dict[str, Any]:
        """
        Compare page states before and after actions
        
        Args:
            state1_actions: Actions to set up first state
            state2_actions: Actions to set up second state
        
        Returns:
            Dict with page state comparison results
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            result = {
                'success': True,
                'timestamp': datetime.now().isoformat(),
                'states': {}
            }

            # Capture initial state
            initial_state = await self._capture_page_state()
            result['states']['initial'] = initial_state

            # Execute state1 actions and capture
            if state1_actions:
                await self.simulate_user_interactions(state1_actions)
                await self.page.wait_for_timeout(1000)  # Allow state to settle
            
            state1 = await self._capture_page_state()
            result['states']['state1'] = state1

            # Execute state2 actions and capture
            if state2_actions:
                await self.simulate_user_interactions(state2_actions)
                await self.page.wait_for_timeout(1000)  # Allow state to settle
            
            state2 = await self._capture_page_state()
            result['states']['state2'] = state2

            # Compare states
            comparison = self._compare_states(state1, state2)
            result['comparison'] = comparison

            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Page state comparison failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

    async def _capture_page_state(self) -> Dict[str, Any]:
        """Internal method to capture current page state"""
        try:
            state = await self.page.evaluate("""
                () => {
                    return {
                        url: window.location.href,
                        title: document.title,
                        elementCount: document.querySelectorAll('*').length,
                        formCount: document.forms.length,
                        linkCount: document.querySelectorAll('a').length,
                        imageCount: document.images.length,
                        inputCount: document.querySelectorAll('input, textarea, select').length,
                        visibleText: document.body ? document.body.innerText.substring(0, 1000) : '',
                        scrollPosition: {
                            x: window.pageXOffset,
                            y: window.pageYOffset
                        }
                    };
                }
            """)
            return state
        except:
            return {'error': 'Failed to capture page state'}

    def _compare_states(self, state1: Dict[str, Any], state2: Dict[str, Any]) -> Dict[str, Any]:
        """Internal method to compare two page states"""
        try:
            comparison = {
                'url_changed': state1.get('url') != state2.get('url'),
                'title_changed': state1.get('title') != state2.get('title'),
                'element_count_diff': state2.get('elementCount', 0) - state1.get('elementCount', 0),
                'form_count_diff': state2.get('formCount', 0) - state1.get('formCount', 0),
                'scroll_changed': (
                    state1.get('scrollPosition', {}).get('y', 0) != 
                    state2.get('scrollPosition', {}).get('y', 0)
                ),
                'content_similarity': self._calculate_text_similarity(
                    state1.get('visibleText', ''),
                    state2.get('visibleText', '')
                )
            }
            return comparison
        except:
            return {'error': 'Failed to compare states'}

    def _calculate_text_similarity(self, text1: str, text2: str) -> float:
        """Calculate text similarity between two strings"""
        try:
            if not text1 and not text2:
                return 1.0
            if not text1 or not text2:
                return 0.0
            
            # Simple Jaccard similarity
            words1 = set(text1.lower().split())
            words2 = set(text2.lower().split())
            
            intersection = words1.intersection(words2)
            union = words1.union(words2)
            
            return len(intersection) / len(union) if union else 0.0
        except:
            return 0.0

    async def generate_test_report(self, test_results: List[Dict[str, Any]], 
                                 report_name: str = "test_report") -> Dict[str, Any]:
        """
        Generate comprehensive test report from multiple test results
        
        Args:
            test_results: List of test result dictionaries
            report_name: Name for the report file
        
        Returns:
            Dict with test report generation results
        """
        try:
            import json
            from datetime import datetime
            
            report = {
                'report_name': report_name,
                'generated_at': datetime.now().isoformat(),
                'summary': {
                    'total_tests': len(test_results),
                    'passed': 0,
                    'failed': 0,
                    'success_rate': 0.0
                },
                'test_results': test_results,
                'metadata': {
                    'url': self.page.url if self.page else 'No active page',
                    'user_agent': 'NexusBrowser Testing Framework',
                    'environment': 'Production Testing'
                }
            }

            # Calculate summary statistics
            for test_result in test_results:
                if test_result.get('success', False):
                    report['summary']['passed'] += 1
                else:
                    report['summary']['failed'] += 1

            if report['summary']['total_tests'] > 0:
                report['summary']['success_rate'] = (
                    report['summary']['passed'] / report['summary']['total_tests'] * 100
                )

            # Save report to file
            report_filename = f"{report_name}_{int(datetime.now().timestamp())}.json"
            with open(report_filename, 'w') as f:
                json.dump(report, f, indent=2)

            return {
                'success': True,
                'report_file': report_filename,
                'summary': report['summary'],
                'timestamp': datetime.now().isoformat()
            }

        except Exception as e:
            return {
                'success': False,
                'error': f'Test report generation failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

