    async def handle_multi_tab_operations(self, max_tabs: int = 5) -> Dict[str, Any]:
        """
        Handle operations across multiple browser tabs/windows
        
        Args:
            max_tabs: Maximum number of tabs to manage simultaneously
        
        Returns:
            Dict with multi-tab operation status
        """
        try:
            from datetime import datetime
            
            if not self.page:
                return {
                    'success': False,
                    'error': 'No active page available',
                    'timestamp': datetime.now().isoformat()
                }

            result = {
                'success': True,
                'max_tabs': max_tabs,
                'tabs': [],
                'current_tab_index': 0,
                'timestamp': datetime.now().isoformat()
            }

            # Get all pages (tabs) in the context
            pages = self.page.context.pages
            result['total_tabs'] = len(pages)
            
            # Store tab information
            for i, page in enumerate(pages[:max_tabs]):
                tab_info = {
                    'index': i,
                    'url': page.url,
                    'title': await page.title() if page else 'Unknown',
                    'is_current': page == self.page
                }
                result['tabs'].append(tab_info)
            
            # Open a new tab if requested
            if len(pages) < max_tabs:
                new_page = await self.page.context.new_page()
                await new_page.goto('https://httpbin.org/html')
                result['new_tab_created'] = True
                result['new_tab_url'] = new_page.url
                
                # Switch between tabs demonstration
                await self.page.bring_to_front()
                result['switched_back_to_original'] = True
            
            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Multi-tab operations failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

    async def extract_metadata(self) -> Dict[str, Any]:
        """
        Extract comprehensive metadata from the current page
        
        Returns:
            Dict with page metadata including SEO, social media tags, etc.
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            from datetime import datetime
            
            metadata = await self.page.evaluate("""
                () => {
                    // Extract various metadata
                    const meta = {
                        // Basic metadata
                        title: document.title,
                        description: document.querySelector('meta[name="description"]')?.content || '',
                        keywords: document.querySelector('meta[name="keywords"]')?.content || '',
                        author: document.querySelector('meta[name="author"]')?.content || '',
                        charset: document.charset,
                        language: document.documentElement.lang || '',
                        
                        // SEO metadata
                        canonical: document.querySelector('link[rel="canonical"]')?.href || '',
                        robots: document.querySelector('meta[name="robots"]')?.content || '',
                        
                        // Open Graph metadata
                        og: {
                            title: document.querySelector('meta[property="og:title"]')?.content || '',
                            description: document.querySelector('meta[property="og:description"]')?.content || '',
                            image: document.querySelector('meta[property="og:image"]')?.content || '',
                            url: document.querySelector('meta[property="og:url"]')?.content || '',
                            type: document.querySelector('meta[property="og:type"]')?.content || ''
                        },
                        
                        // Twitter Card metadata
                        twitter: {
                            card: document.querySelector('meta[name="twitter:card"]')?.content || '',
                            title: document.querySelector('meta[name="twitter:title"]')?.content || '',
                            description: document.querySelector('meta[name="twitter:description"]')?.content || '',
                            image: document.querySelector('meta[name="twitter:image"]')?.content || ''
                        },
                        
                        // Document statistics
                        stats: {
                            images: document.images.length,
                            links: document.links.length,
                            forms: document.forms.length,
                            scripts: document.scripts.length,
                            stylesheets: document.styleSheets.length,
                            iframes: document.querySelectorAll('iframe').length
                        },
                        
                        // Schema.org structured data
                        structuredData: Array.from(document.querySelectorAll('script[type="application/ld+json"]'))
                            .map(s => {
                                try {
                                    return JSON.parse(s.textContent);
                                } catch {
                                    return null;
                                }
                            }).filter(Boolean)
                    };
                    
                    return meta;
                }
            """)
            
            return {
                'success': True,
                'url': self.page.url,
                'metadata': metadata,
                'timestamp': datetime.now().isoformat()
            }

        except Exception as e:
            return {
                'success': False,
                'error': f'Metadata extraction failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

    async def handle_iframe_content(self, iframe_selector: str = 'iframe') -> Dict[str, Any]:
        """
        Handle and extract content from iframes on the page
        
        Args:
            iframe_selector: CSS selector for targeting specific iframes
        
        Returns:
            Dict with iframe content and information
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            from datetime import datetime
            
            result = {
                'success': True,
                'iframes': [],
                'total_iframes': 0,
                'timestamp': datetime.now().isoformat()
            }
            
            # Get all iframe elements
            iframe_elements = await self.page.query_selector_all(iframe_selector)
            result['total_iframes'] = len(iframe_elements)
            
            for i, iframe_element in enumerate(iframe_elements[:5]):  # Limit to first 5
                iframe_info = {
                    'index': i,
                    'attributes': {}
                }
                
                # Get iframe attributes
                iframe_info['attributes'] = await iframe_element.evaluate("""
                    (iframe) => ({
                        src: iframe.src,
                        id: iframe.id,
                        name: iframe.name,
                        width: iframe.width,
                        height: iframe.height,
                        sandbox: iframe.sandbox.toString()
                    })
                """)
                
                # Try to access iframe content (may be blocked by same-origin policy)
                try:
                    frame = await iframe_element.content_frame()
                    if frame:
                        iframe_info['accessible'] = True
                        iframe_info['url'] = frame.url
                        iframe_info['title'] = await frame.title()
                        
                        # Extract some content from iframe
                        iframe_content = await frame.evaluate("""
                            () => ({
                                text: document.body?.innerText?.substring(0, 500) || '',
                                links: Array.from(document.querySelectorAll('a')).length,
                                images: Array.from(document.querySelectorAll('img')).length
                            })
                        """)
                        iframe_info['content_summary'] = iframe_content
                    else:
                        iframe_info['accessible'] = False
                        iframe_info['note'] = 'Frame not accessible (cross-origin or other restriction)'
                except Exception as e:
                    iframe_info['accessible'] = False
                    iframe_info['error'] = str(e)
                
                result['iframes'].append(iframe_info)
            
            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Iframe handling failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

