        config = {'page_changes': {'duration': duration, 'check_interval': check_interval}}
        result = await self.unified_monitoring.monitor(['page_changes'], config, duration)
        
        # Maintain backward compatibility by restructuring the result
        if result['success'] and 'page_changes' in result.get('monitoring_results', {}):
            page_data = result['monitoring_results']['page_changes']['data']
