    async def handle_popup_windows(self) -> Dict[str, Any]:
        """
        Detect and handle popup windows
        
        Returns:
            Dict with popup handling results
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            from datetime import datetime
            
            result = {
                'success': True,
                'popups_detected': [],
                'popups_handled': 0,
                'timestamp': datetime.now().isoformat()
            }
            
            # Set up popup handler
            popup_pages = []
            
            def handle_popup(popup):
                popup_pages.append(popup)
                result['popups_detected'].append({
                    'url': popup.url,
                    'timestamp': datetime.now().isoformat()
                })
            
            # Listen for popup events
            self.page.context.on('page', handle_popup)
            
            # Try to trigger popups by clicking links with target="_blank"
            popup_triggers = await self.page.evaluate("""
                () => {
                    const popupLinks = Array.from(document.querySelectorAll('a[target="_blank"], a[target="new"]'));
                    return popupLinks.map(link => ({
                        href: link.href,
                        text: link.textContent.trim(),
                        target: link.target
                    }));
                }
            """)
            
            result['potential_popup_triggers'] = len(popup_triggers)
            
            # Handle any detected popups
            for popup_page in popup_pages:
                try:
                    # Get popup information
                    popup_info = {
                        'url': popup_page.url,
                        'title': await popup_page.title(),
                        'action': 'closed'
                    }
                    
                    # Close the popup
                    await popup_page.close()
                    result['popups_handled'] += 1
                    
                    result['popups_detected'].append(popup_info)
                except:
                    pass
            
            # Also check for modal/dialog popups on the page
            dialog_check = await self.page.evaluate("""
                () => {
                    const modals = document.querySelectorAll('.modal, .popup, .dialog, [role="dialog"]');
                    const visibleModals = Array.from(modals).filter(modal => {
                        const style = window.getComputedStyle(modal);
                        return style.display !== 'none' && style.visibility !== 'hidden';
                    });
                    
                    return {
                        totalModals: modals.length,
                        visibleModals: visibleModals.length,
                        modalInfo: visibleModals.map(modal => ({
                            className: modal.className,
                            id: modal.id,
                            role: modal.getAttribute('role')
                        }))
                    };
                }
            """)
            
            result['modal_dialogs'] = dialog_check
            
            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Popup handling failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

    async def extract_media_content(self) -> Dict[str, Any]:
        """
        Extract all media content (images, videos, audio) from the page
        
        Returns:
            Dict with media content information
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            from datetime import datetime
            from urllib.parse import urljoin
            
            current_url = self.page.url
            
            media_data = await self.page.evaluate("""
                () => {
                    // Extract images
                    const images = Array.from(document.images).map(img => ({
                        src: img.src,
                        alt: img.alt,
                        title: img.title,
                        width: img.naturalWidth,
                        height: img.naturalHeight,
                        loading: img.loading,
                        complete: img.complete
                    }));
                    
                    // Extract videos
                    const videos = Array.from(document.querySelectorAll('video')).map(video => ({
                        src: video.src || (video.querySelector('source') ? video.querySelector('source').src : null),
                        poster: video.poster,
                        duration: video.duration,
                        width: video.videoWidth,
                        height: video.videoHeight,
                        controls: video.controls,
                        autoplay: video.autoplay,
                        muted: video.muted
                    }));
                    
                    // Extract audio
                    const audios = Array.from(document.querySelectorAll('audio')).map(audio => ({
                        src: audio.src || (audio.querySelector('source') ? audio.querySelector('source').src : null),
                        duration: audio.duration,
                        controls: audio.controls,
                        autoplay: audio.autoplay,
                        muted: audio.muted
                    }));
                    
                    // Extract background images from CSS
                    const elementsWithBg = Array.from(document.querySelectorAll('*')).filter(el => {
                        const bg = window.getComputedStyle(el).backgroundImage;
                        return bg && bg !== 'none';
                    }).map(el => {
                        const bg = window.getComputedStyle(el).backgroundImage;
                        const urlMatch = bg.match(/url\(["']?(.+?)["']?\)/);
                        return urlMatch ? urlMatch[1] : null;
                    }).filter(Boolean);
                    
                    // Extract iframes (potential embedded media)
                    const iframes = Array.from(document.querySelectorAll('iframe')).map(iframe => ({
                        src: iframe.src,
                        title: iframe.title,
                        width: iframe.width,
                        height: iframe.height,
                        isYouTube: iframe.src.includes('youtube.com') || iframe.src.includes('youtu.be'),
                        isVimeo: iframe.src.includes('vimeo.com')
                    }));
                    
                    return {
                        images: images,
                        videos: videos,
                        audios: audios,
                        backgroundImages: elementsWithBg,
                        iframes: iframes
                    };
                }
            """)
            
            # Process and categorize media
            result = {
                'success': True,
                'url': current_url,
                'media_summary': {
                    'total_images': len(media_data['images']),
                    'total_videos': len(media_data['videos']),
                    'total_audio': len(media_data['audios']),
                    'background_images': len(media_data['backgroundImages']),
                    'embedded_media': len([i for i in media_data['iframes'] if i.get('isYouTube') or i.get('isVimeo')])
                },
                'images': media_data['images'][:20],  # Limit to first 20
                'videos': media_data['videos'],
                'audio': media_data['audios'],
                'embedded_media': [i for i in media_data['iframes'] if i.get('isYouTube') or i.get('isVimeo')],
                'timestamp': datetime.now().isoformat()
            }
            
            # Calculate total media size estimate (based on dimensions)
            total_pixels = sum(img.get('width', 0) * img.get('height', 0) for img in media_data['images'])
            result['media_statistics'] = {
                'total_image_pixels': total_pixels,
                'average_image_size': total_pixels // len(media_data['images']) if media_data['images'] else 0,
                'images_loaded': sum(1 for img in media_data['images'] if img.get('complete')),
                'lazy_loaded_images': sum(1 for img in media_data['images'] if img.get('loading') == 'lazy')
            }
            
            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Media extraction failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

    async def perform_visual_regression(self, baseline_path: str = None) -> Dict[str, Any]:
        """
        Perform visual regression testing by comparing screenshots
        
        Args:
            baseline_path: Path to baseline screenshot for comparison
        
        Returns:
            Dict with visual regression results
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            from datetime import datetime
            from pathlib import Path
            import base64
            
            result = {
                'success': True,
                'url': self.page.url,
                'timestamp': datetime.now().isoformat()
            }
            
            # Take current screenshot
            current_screenshot_path = f"visual_regression_{int(datetime.now().timestamp())}.png"
            current_screenshot = await self.page.screenshot(
                path=current_screenshot_path,
                full_page=True
            )
            
            result['current_screenshot'] = current_screenshot_path
            result['screenshot_size'] = len(current_screenshot)
            
            # Get page dimensions
            dimensions = await self.page.evaluate("""
                () => ({
                    viewport: {
                        width: window.innerWidth,
                        height: window.innerHeight
                    },
                    document: {
                        width: document.documentElement.scrollWidth,
                        height: document.documentElement.scrollHeight
                    }
                })
            """)
            result['page_dimensions'] = dimensions
            
            if baseline_path and Path(baseline_path).exists():
                # Compare with baseline
                with open(baseline_path, 'rb') as f:
                    baseline_data = f.read()
                
                # Simple comparison (in production, use image diff libraries)
                if len(baseline_data) == len(current_screenshot):
                    result['comparison'] = {
                        'status': 'identical',
                        'baseline_size': len(baseline_data),
                        'current_size': len(current_screenshot),
                        'difference': 0
                    }
                else:
                    size_diff = abs(len(baseline_data) - len(current_screenshot))
                    diff_percent = (size_diff / len(baseline_data)) * 100
                    result['comparison'] = {
                        'status': 'different',
                        'baseline_size': len(baseline_data),
                        'current_size': len(current_screenshot),
                        'difference': size_diff,
                        'difference_percent': round(diff_percent, 2)
                    }
            else:
                result['comparison'] = {
                    'status': 'no_baseline',
                    'note': 'No baseline provided, current screenshot saved as potential baseline'
                }
            
            # Capture specific elements for targeted regression testing
            critical_elements = await self.page.evaluate("""
                () => {
                    const elements = [];
                    
                    // Capture header
                    const header = document.querySelector('header, [role="banner"], .header');
                    if (header) {
                        const rect = header.getBoundingClientRect();
                        elements.push({
                            type: 'header',
                            position: {x: rect.x, y: rect.y, width: rect.width, height: rect.height}
                        });
                    }
                    
                    // Capture navigation
                    const nav = document.querySelector('nav, [role="navigation"], .nav');
                    if (nav) {
                        const rect = nav.getBoundingClientRect();
                        elements.push({
                            type: 'navigation',
                            position: {x: rect.x, y: rect.y, width: rect.width, height: rect.height}
                        });
                    }
                    
                    // Capture main content
                    const main = document.querySelector('main, [role="main"], .main, #content');
                    if (main) {
                        const rect = main.getBoundingClientRect();
                        elements.push({
                            type: 'main_content',
                            position: {x: rect.x, y: rect.y, width: rect.width, height: rect.height}
                        });
                    }
                    
                    return elements;
                }
            """)
            
            result['critical_elements'] = critical_elements
            
            # Clean up screenshot file if not needed
            try:
                Path(current_screenshot_path).unlink()
            except:
                pass
            
            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'Visual regression failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

    async def execute_javascript_code(self, code: str,
                                    safe_mode: bool = True) -> Dict[str, Any]:
        """
        Execute custom JavaScript code on the page with safety controls
        
        Args:
            code: JavaScript code to execute
            safe_mode: Whether to apply safety restrictions
        
        Returns:
            Dict with execution results
        """
        if not self.page:
            return {
                'success': False,
                'error': 'No active page available',
                'timestamp': datetime.now().isoformat()
            }

        try:
            from datetime import datetime
            
            result = {
                'success': True,
                'safe_mode': safe_mode,
                'timestamp': datetime.now().isoformat()
            }
            
            if safe_mode:
                # Check for potentially dangerous patterns
                dangerous_patterns = [
                    'eval(',
                    'Function(',
                    'innerHTML',
                    'document.write',
                    'window.location',
                    '.cookie',
                    'localStorage',
                    'sessionStorage',
                    'fetch(',
                    'XMLHttpRequest',
                    'WebSocket'
                ]
                
                code_lower = code.lower()
                violations = [pattern for pattern in dangerous_patterns if pattern.lower() in code_lower]
                
                if violations:
                    return {
                        'success': False,
                        'error': 'Potentially dangerous code patterns detected',
                        'violations': violations,
                        'safe_mode': True,
                        'timestamp': datetime.now().isoformat()
                    }
            
            # Execute the code
            try:
                execution_result = await self.page.evaluate(f"""
                    () => {{
                        try {{
                            const result = (() => {{
                                {code}
                            }})();
                            return {{
                                success: true,
                                result: result,
                                type: typeof result
                            }};
                        }} catch (error) {{
                            return {{
                                success: false,
                                error: error.toString(),
                                stack: error.stack
                            }};
                        }}
                    }}
                """)
                
                result.update(execution_result)
                
                # Log console output if any
                console_logs = []
                
                def capture_console(msg):
                    console_logs.append({
                        'type': msg.type,
                        'text': msg.text
                    })
                
                # Temporarily capture console
                self.page.on('console', capture_console)
                
                # Give time for any async operations
                await self.page.wait_for_timeout(100)
                
                result['console_output'] = console_logs
                
            except Exception as e:
                result['success'] = False
                result['error'] = str(e)
            
            return result

        except Exception as e:
            return {
                'success': False,
                'error': f'JavaScript execution failed: {str(e)}',
                'timestamp': datetime.now().isoformat()
            }

