class OptimizationEngine:
    """Optimize code through AST transformation"""
    
    async def optimize_ast(self, tree: ast.AST) -> ast.AST:
        """Apply optimizations to AST"""
        # Apply multiple optimization passes
        tree = await self._constant_folding(tree)
        tree = await self._dead_code_elimination(tree)
        tree = await self._loop_optimization(tree)
        tree = await self._function_inlining(tree)
        
        return tree
    
    async def _constant_folding(self, tree: ast.AST) -> ast.AST:
        """Fold constant expressions"""
        class ConstantFolder(ast.NodeTransformer):
            def visit_BinOp(self, node):
                self.generic_visit(node)
                
                # Check if both operands are constants
                if isinstance(node.left, ast.Constant) and isinstance(node.right, ast.Constant):
                    try:
                        # Evaluate operation
                        if isinstance(node.op, ast.Add):
                            value = node.left.value + node.right.value
                        elif isinstance(node.op, ast.Sub):
                            value = node.left.value - node.right.value
                        elif isinstance(node.op, ast.Mult):
                            value = node.left.value * node.right.value
                        elif isinstance(node.op, ast.Div):
                            value = node.left.value / node.right.value
                        else:
                            return node
                        
                        return ast.Constant(value=value)
                    except:
                        pass
                
                return node
        
        folder = ConstantFolder()
        return folder.visit(tree)
    
    async def _dead_code_elimination(self, tree: ast.AST) -> ast.AST:
        """Remove dead code"""
        class DeadCodeEliminator(ast.NodeTransformer):
            def visit_If(self, node):
                self.generic_visit(node)
                
                # Check for constant condition
                if isinstance(node.test, ast.Constant):
                    if node.test.value:
                        # Always true - keep only if body
                        return node.body
                    else:
                        # Always false - keep only else body
                        return node.orelse if node.orelse else ast.Pass()
                
                return node
        
        eliminator = DeadCodeEliminator()
        return eliminator.visit(tree)
    
    async def _loop_optimization(self, tree: ast.AST) -> ast.AST:
        """Optimize loops"""
        class LoopOptimizer(ast.NodeTransformer):
            def visit_For(self, node):
                self.generic_visit(node)
                
                # Check for range loops that can be optimized
                if isinstance(node.iter, ast.Call):
                    if isinstance(node.iter.func, ast.Name) and node.iter.func.id == 'range':
                        # Can potentially unroll small loops
                        if len(node.iter.args) == 1:
                            if isinstance(node.iter.args[0], ast.Constant):
                                loop_count = node.iter.args[0].value
                                
                                # Unroll very small loops
                                if loop_count <= 3:
                                    # Create unrolled statements
                                    unrolled = []
                                    for i in range(loop_count):
                                        # Clone loop body with i substituted
                                        # This is simplified
                                        unrolled.extend(node.body)
                                    
                                    return unrolled
                
                return node
        
        optimizer = LoopOptimizer()
        return optimizer.visit(tree)
    
    async def _function_inlining(self, tree: ast.AST) -> ast.AST:
        """Inline small functions"""
        # This is complex and simplified here
        return tree

class MutationGenerator:
    """Generate mutations for genetic programming"""
    
    async def mutate_ast(self, tree: ast.AST) -> ast.AST:
        """Apply random mutation to AST"""
        # Clone tree first
        mutated = copy.deepcopy(tree)
        
        # Choose random mutation
        mutation_type = random.choice([
            'swap_operands',
            'change_operator',
            'insert_statement',
            'delete_statement',
            'modify_constant'
        ])
        
        if mutation_type == 'swap_operands':
            mutated = await self._swap_operands(mutated)
        elif mutation_type == 'change_operator':
            mutated = await self._change_operator(mutated)
        elif mutation_type == 'modify_constant':
            mutated = await self._modify_constant(mutated)
        
        return mutated
    
    async def _swap_operands(self, tree: ast.AST) -> ast.AST:
        """Swap operands in binary operations"""
        class OperandSwapper(ast.NodeTransformer):
            def visit_BinOp(self, node):
                if random.random() < 0.1:  # 10% chance
                    node.left, node.right = node.right, node.left
                return node
        
        swapper = OperandSwapper()
        return swapper.visit(tree)
    
    async def _change_operator(self, tree: ast.AST) -> ast.AST:
        """Change operators randomly"""
        class OperatorChanger(ast.NodeTransformer):
            def visit_BinOp(self, node):
                if random.random() < 0.1:
                    # Change to similar operator
                    if isinstance(node.op, ast.Add):
                        node.op = ast.Sub()
                    elif isinstance(node.op, ast.Sub):
                        node.op = ast.Add()
                    elif isinstance(node.op, ast.Mult):
                        node.op = ast.Div()
                    elif isinstance(node.op, ast.Div):
                        node.op = ast.Mult()
                
                return node
        
        changer = OperatorChanger()
        return changer.visit(tree)
    
    async def _modify_constant(self, tree: ast.AST) -> ast.AST:
        """Modify constants slightly"""
        class ConstantModifier(ast.NodeTransformer):
            def visit_Constant(self, node):
                if isinstance(node.value, (int, float)):
                    if random.random() < 0.1:
                        # Modify by small amount
                        node.value *= random.uniform(0.9, 1.1)
                
                return node
        
        modifier = ConstantModifier()
        return modifier.visit(tree)

class FitnessEvaluator:
    """Evaluate fitness of code for genetic programming"""
    
    async def evaluate_ast(self, tree: ast.AST) -> float:
        """Evaluate fitness of AST"""
        fitness = 0.0
        
        # Size penalty (prefer smaller code)
        node_count = len(list(ast.walk(tree)))
        fitness -= node_count * 0.01
        
        # Complexity penalty
        complexity = await self._calculate_complexity(tree)
        fitness -= complexity * 0.1
        
        # Performance bonus (estimated)
        performance = await self._estimate_performance(tree)
        fitness += performance
        
        return fitness
    
    async def _calculate_complexity(self, tree: ast.AST) -> float:
        """Calculate cyclomatic complexity"""
        complexity = 1  # Base complexity
        
        for node in ast.walk(tree):
            if isinstance(node, (ast.If, ast.While, ast.For)):
                complexity += 1
            elif isinstance(node, ast.BoolOp):
                complexity += len(node.values) - 1
        
        return complexity
    
    async def _estimate_performance(self, tree: ast.AST) -> float:
        """Estimate performance of code"""
        performance = 10.0  # Base performance
        
        for node in ast.walk(tree):
            # Penalize nested loops
            if isinstance(node, ast.For):
                for child in ast.walk(node):
                    if child != node and isinstance(child, ast.For):
                        performance -= 2.0
            
            # Bonus for optimized patterns
            if isinstance(node, ast.ListComp):
                performance += 1.0  # List comprehensions are fast
        
        return max(0, performance)

class CodeSynthesizer:
    """Synthesize code from specifications"""
    
    async def synthesize(self,
                       specification: Dict[str, Any],
                       examples: List[Tuple[Any, Any]] = None) -> str:
        """Synthesize code from specification"""
        func_name = specification.get('name', 'synthesized_func')
        params = specification.get('parameters', [])
        return_type = specification.get('return_type', 'Any')
        description = specification.get('description', '')
        
        # Build function template
        param_str = ', '.join(params)
        
        code = f'''def {func_name}({param_str}):
    """{description}"""
'''
        
        # Add body based on examples
        if examples:
            # Simple pattern matching
            if all(output == input_val * 2 for input_val, output in examples):
                code += f'    return {params[0]} * 2\n'
            elif all(output == input_val + 1 for input_val, output in examples):
                code += f'    return {params[0]} + 1\n'
            else:
                # Default implementation
                code += '    pass\n'
        else:
            # Generate based on description
            if 'add' in description.lower():
                code += f'    return {" + ".join(params)}\n'
            elif 'multiply' in description.lower():
                code += f'    return {" * ".join(params)}\n'
            else:
                code += '    pass\n'
        
        return code

