class SecurityFramework:
    """Comprehensive security framework for NEXUS"""
    
    def __init__(self):
        self.access_control = AccessControl()
        self.encryption_engine = EncryptionEngine()
        self.audit_logger = AuditLogger()
        self.threat_detector = ThreatDetector()
        self.sandboxer = Sandboxer()
        self.validator = InputValidator()
        self.rate_limiter = RateLimiter()
        self.auth_manager = AuthenticationManager()
        
    async def secure_execute(self,
                           func: Callable,
                           user_context: Dict[str, Any],
                           *args, **kwargs) -> Any:
        """Execute function with security checks"""
        # Check authentication
        if not await self.auth_manager.is_authenticated(user_context):
            raise SecurityError("Not authenticated")
        
        # Check authorization
        if not await self.access_control.is_authorized(user_context, func):
            raise SecurityError("Not authorized")
        
        # Check rate limits
        if not await self.rate_limiter.check_limit(user_context['user_id']):
            raise SecurityError("Rate limit exceeded")
        
        # Validate inputs
        if not await self.validator.validate_inputs(args, kwargs):
            raise ValueError("Invalid inputs")
        
        # Detect threats
        threat_level = await self.threat_detector.assess_threat(user_context, func, args)
        if threat_level > 0.7:
            await self.audit_logger.log_threat(user_context, threat_level)
            raise SecurityError("Potential threat detected")
        
        # Execute in sandbox if needed
        if threat_level > 0.3:
            result = await self.sandboxer.execute(func, *args, **kwargs)
        else:
            result = await func(*args, **kwargs)
        
        # Audit log
        await self.audit_logger.log_execution(user_context, func, result)
        
        return result

class AccessControl:
    """Role-based access control"""
    
    def __init__(self):
        self.roles: Dict[str, Set[str]] = {
            'admin': {'*'},  # All permissions
            'user': {'read', 'write', 'execute'},
            'guest': {'read'}
        }
        self.user_roles: Dict[str, str] = {}
        self.function_permissions: Dict[str, str] = {}
        
    async def is_authorized(self,
                          user_context: Dict[str, Any],
                          func: Callable) -> bool:
        """
        Check if user is authorized for function
        
        UNIFIED SYSTEM: This method now uses the UnifiedAuthenticationManager
        for consistent authorization checking.
        """
        func_name = func.__name__ if hasattr(func, '__name__') else str(func)
        return await self.auth_manager.authorize(user_context, func_name, 'execute')
    
    async def grant_role(self, user_id: str, role: str):
        """Grant role to user"""
        if role in self.roles:
            self.user_roles[user_id] = role
    
    async def revoke_role(self, user_id: str):
        """Revoke user role"""
        if user_id in self.user_roles:
            del self.user_roles[user_id]

class EncryptionEngine:
    """Handle encryption and decryption"""
    
    def __init__(self):
        self.key = secrets.token_bytes(32)  # 256-bit key
        
    async def encrypt(self, data: bytes) -> bytes:
        """Encrypt data"""
        # Simple XOR encryption (in production use proper encryption)
        encrypted = bytearray()
        
        for i, byte in enumerate(data):
            key_byte = self.key[i % len(self.key)]
            encrypted.append(byte ^ key_byte)
        
        return bytes(encrypted)
    
    async def decrypt(self, encrypted_data: bytes) -> bytes:
        """Decrypt data"""
        # XOR is symmetric
        return await self.encrypt(encrypted_data)
    
    async def hash_password(self, password: str) -> str:
        """Hash password securely"""
        salt = secrets.token_bytes(16)
        hashed = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        
        return base64.b64encode(salt + hashed).decode()
    
    async def verify_password(self, password: str, hashed: str) -> bool:
        """Verify password against hash"""
        try:
            decoded = base64.b64decode(hashed.encode())
            salt = decoded[:16]
            stored_hash = decoded[16:]
            
            test_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
            
            return hmac.compare_digest(stored_hash, test_hash)
        except:
            return False

class AuditLogger:
    """Audit logging for security events"""
    
    def __init__(self):
        self.log_file = 'nexus_audit.log'
        self.events: List[Dict[str, Any]] = []
        
    async def log_execution(self,
                          user_context: Dict[str, Any],
                          func: Callable,
                          result: Any):
        """Log function execution"""
        event = {
            'type': 'execution',
            'timestamp': time.time(),
            'user': user_context.get('user_id'),
            'function': func.__name__ if hasattr(func, '__name__') else str(func),
            'success': True
        }
        
        self.events.append(event)
        await self._write_to_file(event)
    
    async def log_threat(self,
                       user_context: Dict[str, Any],
                       threat_level: float):
        """Log security threat"""
        event = {
            'type': 'threat',
            'timestamp': time.time(),
            'user': user_context.get('user_id'),
            'threat_level': threat_level,
            'action': 'blocked'
        }
        
        self.events.append(event)
        await self._write_to_file(event)
    
    async def _write_to_file(self, event: Dict[str, Any]):
        """Write event to audit log file"""
        try:
            with open(self.log_file, 'a') as f:
                f.write(json.dumps(event) + '\n')
        except Exception as e:
            logger.error(f"Failed to write audit log: {e}")

class ThreatDetector:
    """Detect security threats"""
    
    def __init__(self):
        self.threat_patterns = [
            r'eval\s*\(',
            r'exec\s*\(',
            r'__import__',
            r'os\.system',
            r'subprocess',
            r'\.\.[\\/]',  # Path traversal
            r'<script',  # XSS
            r'DROP\s+TABLE',  # SQL injection
        ]
        
    async def assess_threat(self,
                          user_context: Dict[str, Any],
                          func: Callable,
                          args: tuple) -> float:
        """Assess threat level"""
        threat_level = 0.0
        
        # Check function name
        func_name = func.__name__ if hasattr(func, '__name__') else str(func)
        if any(pattern in func_name.lower() for pattern in ['eval', 'exec', 'system']):
            threat_level += 0.5
        
        # Check arguments
        args_str = str(args)
        for pattern in self.threat_patterns:
            if re.search(pattern, args_str, re.IGNORECASE):
                threat_level += 0.3
        
        # Check user history
        if user_context.get('previous_threats', 0) > 0:
            threat_level += 0.2
        
        return min(1.0, threat_level)

class Sandboxer:
    """Execute code in sandbox"""
    
    def __init__(self):
        self.sandbox_dir = tempfile.mkdtemp(prefix='nexus_sandbox_')
        
    async def execute(self, func: Callable, *args, **kwargs) -> Any:
        """Execute function in sandbox"""
        # Create restricted namespace
        restricted_globals = {
            '__builtins__': {
                'print': print,
                'len': len,
                'range': range,
                'str': str,
                'int': int,
                'float': float,
                'list': list,
                'dict': dict,
                'tuple': tuple,
                'set': set,
                'bool': bool,
                'True': True,
                'False': False,
                'None': None,
            }
        }
        
        # Execute with restrictions
        try:
            if asyncio.iscoroutinefunction(func):
                # Async functions need special handling
                return await func(*args, **kwargs)
            else:
                # Execute in restricted environment
                func.__globals__.update(restricted_globals)
                return func(*args, **kwargs)
        except Exception as e:
            logger.error(f"Sandbox execution failed: {e}")
            raise
    
    def cleanup(self):
        """Clean up sandbox"""
        if os.path.exists(self.sandbox_dir):
            shutil.rmtree(self.sandbox_dir)

class InputValidator:
    """Validate and sanitize inputs"""
    
    async def validate_inputs(self, args: tuple, kwargs: dict) -> bool:
        """Validate function inputs"""
        # Check for dangerous types
        for arg in args:
            if not await self._is_safe_type(arg):
                return False
        
        for value in kwargs.values():
            if not await self._is_safe_type(value):
                return False
        
        return True
    
    async def _is_safe_type(self, value: Any) -> bool:
        """Check if value is safe type"""
        safe_types = (str, int, float, bool, list, dict, tuple, type(None))
        
        if not isinstance(value, safe_types):
            return False
        
        # Recursively check containers
        if isinstance(value, (list, tuple)):
            for item in value:
                if not await self._is_safe_type(item):
                    return False
        
        elif isinstance(value, dict):
            for k, v in value.items():
                if not await self._is_safe_type(k) or not await self._is_safe_type(v):
                    return False
        
        return True
    
    async def sanitize_string(self, text: str) -> str:
        """Sanitize string input"""
        # Remove potential XSS
        text = re.sub(r'<[^>]*>', '', text)
        
        # Remove potential SQL injection
        text = re.sub(r"['\"`;]", '', text)
        
        # Remove path traversal
        text = re.sub(r'\.\.[\\/]', '', text)
        
        return text

class RateLimiter:
    """Rate limiting for API calls"""
    
    def __init__(self):
        self.limits: Dict[str, List[float]] = defaultdict(list)
        self.max_requests = 100
        self.time_window = 60  # seconds
        
    async def check_limit(self, user_id: str) -> bool:
        """Check if user is within rate limit"""
        current_time = time.time()
        
        # Clean old requests
        self.limits[user_id] = [
            t for t in self.limits[user_id]
            if current_time - t < self.time_window
        ]
        
        # Check limit
        if len(self.limits[user_id]) >= self.max_requests:
            return False
        
        # Add current request
        self.limits[user_id].append(current_time)
        return True

class AuthenticationManager:
    """Handle authentication"""
    
    def __init__(self):
        self.sessions: Dict[str, Dict[str, Any]] = {}
        self.tokens: Dict[str, str] = {}
        
    async def authenticate(self, username: str, password: str) -> Optional[str]:
        """
        Authenticate user and return token
        
        UNIFIED SYSTEM: This method now uses the UnifiedAuthenticationManager
        for consistent authentication handling.
        """
        auth_result = await self.auth_manager.authenticate(
            'token', 
            {'username': username, 'password': password}
        )
        
        if auth_result.get('success') and auth_result.get('authenticated'):
            return auth_result.get('token')
        
        return None
    
    async def is_authenticated(self, user_context: Dict[str, Any]) -> bool:
        """
        Check if user is authenticated
        
        UNIFIED SYSTEM: This method now uses the UnifiedAuthenticationManager
        for consistent authentication validation.
        """
        return await self.auth_manager.is_authenticated(user_context)
    
    async def logout(self, token: str):
        """Logout user"""
        if token in self.tokens:
            username = self.tokens[token]
            del self.tokens[token]
            
            if username in self.sessions:
                del self.sessions[username]

class SecurityError(Exception):
    """Security exception"""
    pass

