class ConfigurationManager:
    """Manage NEXUS configuration"""
    
    def __init__(self, config_file: str = 'nexus_config.json'):
        self.config_file = config_file
        self.config: Dict[str, Any] = self._load_default_config()
        self.environment = self._detect_environment()
        self.validators: Dict[str, Callable] = {}
        self._load_config()
        
    def _load_default_config(self) -> Dict[str, Any]:
        """Load default configuration"""
        return {
            'nexus': {
                'version': '1.0.0',
                'mode': 'production',
                'debug': False,
                'log_level': 'INFO'
            },
            'quantum': {
                'max_qubits': 1024,
                'decoherence_rate': 0.001,
                'error_correction': True,
                'superposition_limit': 1000000
            },
            'browser': {
                'headless': False,
                'timeout': 30000,
                'viewport': {'width': 1920, 'height': 1080},
                'user_agent': 'Mozilla/5.0',
                'stealth_mode': True
            },
            'swarm': {
                'max_agents': 1000,
                'default_cluster_size': 10,
                'evolution_generations': 10,
                'consensus_method': 'byzantine_fault_tolerant'
            },
            'performance': {
                'cache_size': 10000,
                'thread_pool_size': None,  # Auto-detect
                'memory_limit': 0.8,  # 80% of system memory
                'gc_threshold': 0.7
            },
            'security': {
                'enable_sandbox': True,
                'rate_limit': 100,
                'session_timeout': 3600,
                'encryption_key': None  # Generated at runtime
            },
            'paths': {
                'data_dir': './nexus_data',
                'log_dir': './nexus_logs',
                'cache_dir': './nexus_cache',
                'module_dir': './nexus_modules'
            }
        }
    
    def _detect_environment(self) -> str:
        """Detect runtime environment"""
        if os.environ.get('NEXUS_ENV'):
            return os.environ['NEXUS_ENV']
        
        if os.environ.get('DEBUG'):
            return 'development'
        
        return 'production'
    
    def _load_config(self):
        """Load configuration from file"""
        if os.path.exists(self.config_file):
            try:
                with open(self.config_file, 'r') as f:
                    file_config = json.load(f)
                
                # Merge with defaults
                self._deep_merge(self.config, file_config)
                
            except Exception as e:
                logger.error(f"Failed to load config: {e}")
    
    def _deep_merge(self, base: dict, override: dict):
        """Deep merge dictionaries"""
        for key, value in override.items():
            if key in base and isinstance(base[key], dict) and isinstance(value, dict):
                self._deep_merge(base[key], value)
            else:
                base[key] = value
    
    def get(self, key_path: str, default: Any = None) -> Any:
        """Get configuration value"""
        keys = key_path.split('.')
        value = self.config
        
        for key in keys:
            if isinstance(value, dict) and key in value:
                value = value[key]
            else:
                return default
        
        return value
    
    def set(self, key_path: str, value: Any):
        """Set configuration value"""
        keys = key_path.split('.')
        config = self.config
        
        # Navigate to parent
        for key in keys[:-1]:
            if key not in config:
                config[key] = {}
            config = config[key]
        
        # Validate if validator exists
        if key_path in self.validators:
            if not self.validators[key_path](value):
                raise ValueError(f"Invalid value for {key_path}")
        
        # Set value
        config[keys[-1]] = value
    
    def add_validator(self, key_path: str, validator: Callable):
        """Add configuration validator"""
        self.validators[key_path] = validator
    
    def save(self):
        """Save configuration to file"""
        try:
            with open(self.config_file, 'w') as f:
                json.dump(self.config, f, indent=2)
        except Exception as e:
            logger.error(f"Failed to save config: {e}")
    
    def validate(self) -> List[str]:
        """Validate entire configuration"""
        errors = []
        
        # Check required paths exist
        for path_key in ['data_dir', 'log_dir', 'cache_dir']:
            path = self.get(f'paths.{path_key}')
            if path and not os.path.exists(path):
                try:
                    os.makedirs(path)
                except Exception as e:
                    errors.append(f"Cannot create {path_key}: {e}")
        
        # Validate quantum settings
        if self.get('quantum.max_qubits') < 8:
            errors.append("quantum.max_qubits must be at least 8")
        
        # Validate performance settings
        if self.get('performance.memory_limit') > 1.0:
            errors.append("performance.memory_limit must be <= 1.0")
        
        return errors

