class AnomalyDetector:
    """Detect system anomalies"""
    
    def __init__(self):
        self.baseline: Dict[str, float] = {}
        self.anomalies: List[Dict[str, Any]] = []
        self.threshold = 2.0  # Standard deviations
        
    async def detect(self, metric_name: str, value: float) -> bool:
        """Detect if value is anomalous"""
        if metric_name not in self.baseline:
            self.baseline[metric_name] = value
            return False
        
        baseline = self.baseline[metric_name]
        deviation = abs(value - baseline) / (baseline + 0.0001)
        
        is_anomaly = deviation > self.threshold
        
        if is_anomaly:
            self.anomalies.append({
                'metric': metric_name,
                'value': value,
                'baseline': baseline,
                'deviation': deviation,
                'timestamp': time.time()
            })
        
        # Update baseline with exponential moving average
        self.baseline[metric_name] = 0.9 * baseline + 0.1 * value
        
        return is_anomaly

